<?php defined('ALTUMCODE') || die(); if(!fcc_rel_ready())return;$m=fcc_rel_monitor(); ?>
<section class="fp-panel" id="usage"><div class="fp-section-title fp-wrap-heading"><h2><?= $h(fcc_rel_t('monitor')) ?></h2><a class="fp-button fp-button-outline" href="<?= url('partner/admin?usage_csv=1') ?>"><?= $h(fcc_rel_t('export')) ?></a></div><p class="fp-muted"><?= $h(fcc_rel_t('monitor_note')) ?></p>
<div class="fp-usage-metrics"><?php foreach($m['counts'] as $k=>$v): ?><div><small><?= $h(fcc_rel_t($k)) ?></small><strong><?= $v ?></strong></div><?php endforeach ?></div>
<h3><?= $h(fcc_rel_t('daily_usage')) ?></h3><div class="fp-usage-chart" role="img" aria-label="<?= $h(fcc_rel_t('daily_usage')) ?>"><?php $max=max(1,...array_column($m['daily'],'accounts'));foreach($m['daily'] as $day): ?><div title="<?= $h($day['day'].': '.$day['accounts']) ?>"><span><?= (int)$day['accounts'] ?></span><i style="height:<?= max(2,round(100*$day['accounts']/$max)) ?>px"></i><small><?= $h(substr($day['day'],8)) ?></small></div><?php endforeach ?></div>
<div class="fp-usage-columns"><div><h3><?= $h(fcc_rel_t('modules')) ?></h3><?php foreach($m['modules'] as $row): ?><div class="fp-usage-row"><strong><?= $h($names[$row['module']]??fcc_rel_t('other')) ?></strong><span><?= (int)$row['accounts'] ?> <?= $h(fcc_rel_t('accounts')) ?> · <?= (int)$row['views'] ?> <?= $h(fcc_rel_t('views')) ?> · <?= (int)$row['actions'] ?> <?= $h(fcc_rel_t('actions')) ?></span></div><?php endforeach;if(!$m['modules']): ?><p><?= $h(fcc_rel_t('none')) ?></p><?php endif ?></div><div><h3><?= $h(fcc_rel_t('online')) ?></h3><?php foreach($m['online'] as $row): ?><a class="fp-usage-row" href="<?= url('admin/user-view/'.(int)$row['user_id']) ?>"><strong><?= $h($row['name']) ?></strong><small><?= $h(fcc_cc_time($row['last_seen'])) ?></small></a><?php endforeach;if(!$m['online']): ?><p><?= $h(fcc_rel_t('none')) ?></p><?php endif ?></div></div></section>
